        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Tecrübe, yaşlanarak değil, yaşayarak kazanılır; ve zaman insanları değil, armutları olgunlaştırır.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Bekârları çoğalan cemiyet, gizli bir anarşi geçiriyordur. Ya büyük bir inkılâba, ya inhitata gidecektir.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Otobiyografik romanlar, yaratma hürriyetimizi kısıtlar. Orada biz sayısız imkân ve ihtimallerden bazılarını tercih hürriyetini kaybeder, bir tanesi üzerinde billurlaşmaya mecbur kalırız.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Öğleye doğru muayene odasının önü doldu. Sıralarda oturacak yer kalmadığı için yeni gelenler ayakta durdular ve anneler, hasta çocuklarını dizlerine oturtabilmek için duvar diplerine çömeldiler.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Bizden uzaklaşmadıkça bize görünmeyen sıhhat, alışkanlığın verdiği hissizlikle, sağlamların şuurundan kaçıp nasıl ve nereye saklanıyor? Onu ben görüyorum, çünkü benden uzak.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Dünyanın hiçbir Nüzhet'i yalan söylememelidir.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "En basit içtimaî dâvaları anlamayacak kadar yabancı tesirler altında şahsiyetlerini kaybeden bu insanlarla münakaşaya mecbur olmanın küçüklüğünden muzdariptim.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Felâketimizi başka biriyle taksim etmek saadettir fakat annelerle değil, annelerle değil. Annelere anlatılan kederler taksim değil zarbedilmiş (dövülmüş) olur.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Asır tereddüt ediyor.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Ben esrarlıyım, ben karanlığım diye bar bar bağıran şeyin esrarı kalır mı?", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Bu kaçan benliklerimizi birbirimizde aramak tecessüsü olmasaydı bir saniye bile konuşabilir miydik?", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Evlenmek insanı yalnızlıktan kurtarmaz, belki daha müthiş bir yalnızlığa atar.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Ben'in Allah'ta yok olmaya koşması azizleri, insanlıkta yok olmaya koşması dâhileri, millette yok olmaya koşması kahramanları yaratmıştır.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Âşıklara haber vermek isterim: Kalbin tüm meseleleri yalnız kalpte halledilir, çünkü bir hissin hakkından ancak başka bir his gelir. Ümitsiz bir aşkın panzehiri ise nefrettir.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Her sıkıntı bir isyan hazırlığıdır. Ruhta başlayan bu hazırlık vücudun hastalanması şeklinde organik bir isyana çevrilir.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "İnsanın kandırdığı en büyük budala kendisidir.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "İki tarafta da arzuyu gurura hesap vermeye çağıran iç muhasebe anları olmasaydı, kendi kendini yiyen aşkın işkenceleri ne kadar azalırdı.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Kendi kendimden nefretimin çerçevelediği ve çirkinleştirdiği bir dünyada yalnızım", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Septisemi, verem, kanser hep boş lakırdı. İnsanı öldüren illet: SIKINTI. Öteki hastalıklar bunların görünüşleridir.", Author = "Peyami Safa" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Peyami_Safa", Text = "Ev kadınlığını hizmetçilik sandığı için kendisini Üniversiteye atan bir kızın kültüründen de, ahlakından da bu memlekete hiçbir hayır gelmez.", Author = "Peyami Safa" },
        };
    }
